using System.Data; using Dapper; using HabitFlow.Domain; using Microsoft.Extensions.Configuration; using Npgsql;
namespace HabitFlow.Infrastructure;
public sealed class DbConnectionFactory(IConfiguration cfg){public async Task<IDbConnection> OpenAsync(CancellationToken ct=default){var c=new NpgsqlConnection(cfg.GetConnectionString("DefaultConnection"));await c.OpenAsync(ct);return c;}}
public sealed class SqlExecutor(DbConnectionFactory f){public async Task<int> ExecuteAsync(string sql,object? p=null,CancellationToken ct=default){using var c=await f.OpenAsync(ct);return await c.ExecuteAsync(new CommandDefinition(sql,p,cancellationToken:ct));} public async Task<IEnumerable<T>> QueryAsync<T>(string sql,object? p=null,CancellationToken ct=default){using var c=await f.OpenAsync(ct);return await c.QueryAsync<T>(new CommandDefinition(sql,p,cancellationToken:ct));} public async Task<T?> QuerySingleOrDefaultAsync<T>(string sql,object? p=null,CancellationToken ct=default){using var c=await f.OpenAsync(ct);return await c.QuerySingleOrDefaultAsync<T>(new CommandDefinition(sql,p,cancellationToken:ct));}}
public sealed class UnitOfWork(DbConnectionFactory factory){public Task<IDbConnection> OpenAsync(CancellationToken ct=default)=>factory.OpenAsync(ct);} 
public sealed class UserRepository(SqlExecutor db):IUserRepository{public Task<User?> GetByIdAsync(Guid id,CancellationToken ct=default)=>db.QuerySingleOrDefaultAsync<User>("select * from habitflow.users where id=@id",new{id},ct); public Task<User?> GetByEmailAsync(string email,CancellationToken ct=default)=>db.QuerySingleOrDefaultAsync<User>("select * from habitflow.users where email=@email",new{email},ct); public async Task<IReadOnlyList<User>> SearchAsync(string? term,CancellationToken ct=default)=>(await db.QueryAsync<User>("select * from habitflow.users where @term is null or email ilike @like or name ilike @like order by created_at desc",new{term=string.IsNullOrWhiteSpace(term)?null:term,like=$"%{term}%"},ct)).ToList(); public Task CreateAsync(User u,CancellationToken ct=default)=>db.ExecuteAsync("insert into habitflow.users(id,name,email,password_hash,photo_url,role,account_status,risk_status,plan,plan_status,wants_premium_notice,onboarding_completed,accepted_terms_at,accepted_privacy_at,last_login_at,last_activity_at,created_at,updated_at) values(@Id,@Name,@Email,@PasswordHash,@PhotoUrl,@Role::text,@AccountStatus::text,@RiskStatus::text,@Plan::text,@PlanStatus::text,@WantsPremiumNotice,@OnboardingCompleted,@AcceptedTermsAt,@AcceptedPrivacyAt,@LastLoginAt,@LastActivityAt,@CreatedAt,@UpdatedAt)",u,ct); public Task UpdateAsync(User u,CancellationToken ct=default)=>db.ExecuteAsync("update habitflow.users set name=@Name, photo_url=@PhotoUrl, role=@Role::text, account_status=@AccountStatus::text, risk_status=@RiskStatus::text, plan=@Plan::text, plan_status=@PlanStatus::text, updated_at=@UpdatedAt where id=@Id",u,ct); public Task AddLoginAttemptAsync(LoginAttempt a,CancellationToken ct=default)=>db.ExecuteAsync("insert into habitflow.login_attempts(id,email,success,ip_address,user_agent,created_at) values(@Id,@Email,@Success,@IpAddress,@UserAgent,@CreatedAt)",a,ct);} 
public sealed class HabitRepository(SqlExecutor db):IHabitRepository{public Task<int> CountActiveByUserAsync(Guid userId,CancellationToken ct=default)=>db.QuerySingleOrDefaultAsync<int>("select count(*) from habitflow.habits where user_id=@userId and is_archived=false",new{userId},ct)!; public async Task<IReadOnlyList<Habit>> ListByUserAsync(Guid userId,CancellationToken ct=default)=>(await db.QueryAsync<Habit>("select * from habitflow.habits where user_id=@userId order by is_archived, created_at desc",new{userId},ct)).ToList(); public Task<Habit?> GetAsync(Guid id,CancellationToken ct=default)=>db.QuerySingleOrDefaultAsync<Habit>("select * from habitflow.habits where id=@id",new{id},ct); public Task CreateAsync(Habit h,CancellationToken ct=default)=>db.ExecuteAsync("insert into habitflow.habits(id,user_id,name,color,category,is_archived,archived_at,created_at,updated_at) values(@Id,@UserId,@Name,@Color,@Category,@IsArchived,@ArchivedAt,@CreatedAt,@UpdatedAt)",h,ct); public Task UpdateAsync(Habit h,CancellationToken ct=default)=>db.ExecuteAsync("update habitflow.habits set name=@Name,color=@Color,category=@Category,is_archived=@IsArchived,archived_at=@ArchivedAt,updated_at=@UpdatedAt where id=@Id",h,ct);} 
public sealed class HabitCompletionRepository(SqlExecutor db):IHabitCompletionRepository{public async Task<IReadOnlyList<HabitCompletion>> ListByUserAsync(Guid userId,DateOnly? from=null,CancellationToken ct=default)=>(await db.QueryAsync<HabitCompletion>("select * from habitflow.habit_completions where user_id=@userId and (@from is null or completed_date>=@from)",new{userId,from},ct)).ToList(); public Task AddAsync(HabitCompletion c,CancellationToken ct=default)=>db.ExecuteAsync("insert into habitflow.habit_completions(id,habit_id,user_id,completed_date,created_at) values(@Id,@HabitId,@UserId,@CompletedDate,@CreatedAt) on conflict do nothing",c,ct); public Task DeleteAsync(Guid habitId,DateOnly date,CancellationToken ct=default)=>db.ExecuteAsync("delete from habitflow.habit_completions where habit_id=@habitId and completed_date=@date",new{habitId,date},ct);} 
public sealed class AuditRepository(SqlExecutor db):IAuditRepository{public Task AddSystemAsync(SystemAuditLog l,CancellationToken ct=default)=>db.ExecuteAsync("insert into habitflow.system_audit_logs(id,user_id,user_email,severity,source,action,message,metadata,error_code,error_fingerprint,created_at,read_by_admin) values(@Id,@UserId,@UserEmail,@Severity::text,@Source,@Action,@Message,@Metadata::jsonb,@ErrorCode,@ErrorFingerprint,@CreatedAt,@ReadByAdmin)",l,ct); public async Task<IReadOnlyList<SystemAuditLog>> RecentAsync(CancellationToken ct=default)=>(await db.QueryAsync<SystemAuditLog>("select * from habitflow.system_audit_logs order by created_at desc limit 200",null,ct)).ToList();}
public sealed class AdminAuditRepository(SqlExecutor db):IAdminAuditRepository{public Task AddAsync(AdminAuditLog l,CancellationToken ct=default)=>db.ExecuteAsync("insert into habitflow.admin_audit_logs(id,admin_user_id,admin_email,action,target_user_id,target_user_email,reason,metadata,created_at) values(@Id,@AdminUserId,@AdminEmail,@Action,@TargetUserId,@TargetUserEmail,@Reason,@Metadata::jsonb,@CreatedAt)",l,ct);} 
public sealed class SettingsRepository(SqlExecutor db):ISettingsRepository{public Task<SystemSetting?> GetAsync(string key,CancellationToken ct=default)=>db.QuerySingleOrDefaultAsync<SystemSetting>("select * from habitflow.system_settings where key=@key",new{key},ct); public Task UpsertAsync(SystemSetting s,CancellationToken ct=default)=>db.ExecuteAsync("insert into habitflow.system_settings(key,value,updated_at,updated_by) values(@Key,@Value::jsonb,@UpdatedAt,@UpdatedBy) on conflict(key) do update set value=@Value::jsonb,updated_at=@UpdatedAt,updated_by=@UpdatedBy",s,ct); public async Task<IReadOnlyList<SystemSetting>> ListAsync(CancellationToken ct=default)=>(await db.QueryAsync<SystemSetting>("select * from habitflow.system_settings order by key",null,ct)).ToList();}
public sealed class SupportRepository(SqlExecutor db):ISupportRepository{public Task CreateTicketAsync(SupportTicket t,CancellationToken ct=default)=>db.ExecuteAsync("insert into habitflow.support_tickets(id,user_id,protocol,type,status,priority,title,description,source,created_at,updated_at,resolved_at) values(@Id,@UserId,@Protocol,@Type,@Status::text,@Priority,@Title,@Description,@Source,@CreatedAt,@UpdatedAt,@ResolvedAt)",t,ct); public Task AddMessageAsync(SupportMessage m,CancellationToken ct=default)=>db.ExecuteAsync("insert into habitflow.support_messages(id,ticket_id,user_id,role,message,is_sensitive_blocked,created_at) values(@Id,@TicketId,@UserId,@Role,@Message,@IsSensitiveBlocked,@CreatedAt)",m,ct); public async Task<IReadOnlyList<SupportTicket>> ListByUserAsync(Guid userId,CancellationToken ct=default)=>(await db.QueryAsync<SupportTicket>("select * from habitflow.support_tickets where user_id=@userId order by created_at desc",new{userId},ct)).ToList();}
public sealed class LgpdRepository(SqlExecutor db):ILgpdRepository{public Task CreateAsync(LgpdRequest r,CancellationToken ct=default)=>db.ExecuteAsync("insert into habitflow.lgpd_requests(id,user_id,protocol,type,status,notes,rejection_reason,handled_by,created_at,updated_at,completed_at) values(@Id,@UserId,@Protocol,@Type::text,@Status::text,@Notes,@RejectionReason,@HandledBy,@CreatedAt,@UpdatedAt,@CompletedAt)",r,ct); public async Task<IReadOnlyList<LgpdRequest>> ListByUserAsync(Guid userId,CancellationToken ct=default)=>(await db.QueryAsync<LgpdRequest>("select * from habitflow.lgpd_requests where user_id=@userId order by created_at desc",new{userId},ct)).ToList();}
public sealed class BillingRepository(SqlExecutor db):IBillingRepository{public Task AddAsync(BillingEvent e,CancellationToken ct=default)=>db.ExecuteAsync("insert into habitflow.billing_events(id,user_id,provider,event_type,plan,status,amount,metadata,created_at) values(@Id,@UserId,@Provider,@EventType,@Plan::text,@Status,@Amount,@Metadata::jsonb,@CreatedAt)",e,ct);} 
